const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The question specifies a latitude band between 0 and 40 degrees South.
  const latBand = ee.Geometry.Polygon(
    [[[-180, 0], [180, 0], [180, -40], [-180, -40], [-180, 0]]],
    null,
    false
  );

  // The specific date is February 26, 2025. We create a day-long interval.
  const startDate = '2025-02-26';
  const endDate = '2025-02-27';

  // 2. Data Acquisition & Check
  // The International Best Track Archive for Climate Stewardship (IBTrACS) is the authoritative dataset for cyclone tracks.
  // It's a feature collection, not an image collection.
  const ibtracs = ee.ImageCollection('NOAA/IBTRACS/v4').select('usa_wind'); // Select any band just to make it an image collection
  const cyclones = ee.FeatureCollection('NOAA/IBTRACS/v4')
    .filterBounds(latBand)
    .filterDate(startDate, endDate);

  // Check if any cyclone data points exist for the given day and location.
  const collectionSize = cyclones.size().getInfo();
  if (collectionSize === 0) {
    console.log('Cyclone Collection Points (IBTrACS): 0');
    console.log('No cyclone data points found for the specified date and region.');
    // This is a valid result (0 cyclones), so we proceed to the answer, which will be 'No'.
  } else {
      console.log(`Cyclone Collection Points (IBTrACS): ${collectionSize}`);
  }

  // 3. Processing: Identify distinct cyclones.
  // Multiple data points can belong to the same storm at different times.
  // We extract the unique 'sid' (storm identifier) to count the number of distinct cyclones.
  const distinctCycloneIDs = cyclones.aggregate_array('sid').distinct();
  const numberOfDistinctCyclones = distinctCycloneIDs.size().getInfo();

  // 4. Calculation & Validation
  // The question requires a count of distinct cyclones.
  // A result of 0 is a valid calculation, not a failure.
  if (numberOfDistinctCyclones === null || typeof numberOfDistinctCyclones === 'undefined') {
    console.log('Failed to calculate the number of distinct cyclones.');
    console.log('B');
    return;
  }

  // 5. Final Answer
  console.log(`Date: ${startDate}`);
  console.log(`Latitude band: 0 to 40 degrees South`);
  console.log(`Number of distinct tropical cyclones found: ${numberOfDistinctCyclones}`);

  if (numberOfDistinctCyclones >= 3) {
    console.log('A');
  } else {
    console.log('B');
  }
}

